113	  // Normalize rendered branches by the concept's identity within its rendered
114	  // panel. The obstree backend can return the same concept under several
115	  // branches (e.g. one branch per order), each carrying a copy of the same obs
116	  // list. Duplicate branches within one panel merge their obs with the same
117	  // multiset-max union the reducer applies to same-flatName duplicates, so
118	  // copied lists collapse while equal obs within one list survive as distinct
119	  // results. A concept that legitimately renders under two different panels
120	  // stays as two branches. tableData, timelineData, and both result counts
121	  // derive from this list, keeping the header count aligned with rendered rows.
122	  const normalizedTests = useMemo<NormalizedBranch[]>(() => {
123	    const branchesByIdentity = new Map<string, NormalizedBranch>();
124	
125	    for (const key in state.tests) {
126	      const test = state.tests[key] as TestResult;
127	      if (!test.obs || !Array.isArray(test.obs) || test.obs.length === 0) {
128	        continue;
129	      }
130	
131	      const groupKey = deriveGroupKey(test.flatName);
132	      const identity = `${groupKey}_${test.conceptUuid ?? test.flatName}`;
133	      const existing = branchesByIdentity.get(identity);
134	
135	      if (existing) {
136	        existing.flatNames.push(test.flatName);
137	        existing.obs = mergeObsMultisetMax(existing.obs, test.obs);
138	      } else {
139	        branchesByIdentity.set(identity, {
140	          test,
141	          stateKey: key,
142	          flatNames: [test.flatName],
143	          obs: [...test.obs],
144	        });
145	      }
146	    }
147	
148	    return [...branchesByIdentity.values()];
149	  }, [state.tests]);
